import bisect

class Solution:
    def findTheDistanceValue(self, arr1: List[int], arr2: List[int], d: int) -> int:
        arr2.sort()
        ans = 0
        for x in arr1:
            i = bisect.bisect_left(arr2, x)
            near = []
            if i < len(arr2):
                near.append(arr2[i])
            if i > 0:
                near.append(arr2[i - 1])
            if all(abs(x - y) > d for y in near):
                ans += 1
        return ans

