import java.util.Arrays;

class Solution {
    public int findTheDistanceValue(int[] arr1, int[] arr2, int d) {
        Arrays.sort(arr2);
        int ans = 0;
        for (int x : arr1) {
            int i = Arrays.binarySearch(arr2, x);
            if (i < 0) i = -(i + 1); // insertion point
            boolean ok = true;
            if (i < arr2.length && arr2[i] - x <= d) ok = false;
            if (i > 0 && x - arr2[i - 1] <= d) ok = false;
            if (ok) ans++;
        }
        return ans;
    }
}

