    arr2.sort((a, b) => a - b);
    const lowerBound = (arr, t) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < t) lo = mid + 1; else hi = mid;
        }
        return lo;
    };
    let ans = 0;
    for (const x of arr1) {
        const i = lowerBound(arr2, x);
        let ok = true;
        if (i < arr2.length && arr2[i] - x <= d) ok = false;
        if (i > 0 && x - arr2[i - 1] <= d) ok = false;
        if (ok) ans++;
    }
    return ans;
};

